import sys

def process(s):
    stack = []
    for ch in s:
        if ch == "#":
            if stack:
                stack.pop()
        else:
            stack.append(ch)
    return "".join(stack)

def main():
    data = sys.stdin.read().strip().splitlines()
    s = data[0].split("=", 1)[1].strip().strip('"').strip("'")
    t = data[1].split("=", 1)[1].strip().strip('"').strip("'")
    print(process(s) == process(t))

main()

