import sys

class Node:
    def __init__(self, val=0, neighbors=None):
        self.val = val
        self.neighbors = neighbors if neighbors else []

def build_graph(adjList):
    if not adjList:
        return None
    nodes = [Node(i + 1) for i in range(len(adjList))]
    for i, neighbors in enumerate(adjList):
        for nb in neighbors:
            nodes[i].neighbors.append(nodes[nb - 1])
    return nodes[0] if nodes else None

def to_adj_list(node):
    if not node:
        return []
    visited = {}
    def dfs(n):
        if n in visited:
            return visited[n]
        clone = Node(n.val)
        visited[n] = clone
        for nb in n.neighbors:
            clone.neighbors.append(dfs(nb))
        return clone
    dfs(node)
    result = []
    for n in sorted(visited.keys(), key=lambda x: x.val):
        result.append([nb.val for nb in n.neighbors])
    return result

def main():
    data = sys.stdin.read().strip()
    adjList = eval(data.split("=", 1)[1].strip())
    head = build_graph(adjList)
    if not head:
        print([])
        return
    cloned = {}
    def clone(node):
        if node in cloned:
            return cloned[node]
        c = Node(node.val)
        cloned[node] = c
        for nb in node.neighbors:
            c.neighbors.append(clone(nb))
        return c
    clone(head)
