def coinChange(coins, amount):
    INF=amount+1
    dp=[0]+[INF]*amount
    for a in range(1, amount+1):
        for c in coins:
            if c<=a: dp[a]=min(dp[a], dp[a-c]+1)
    return -1 if dp[amount]==INF else dp[amount]

def isAnagram(s, t):
