            hi = mid - 1
    return -1

def maxSubArray(nums):
    best = cur = nums[0]
    for x in nums[1:]:
        cur = max(x, cur + x)
        best = max(best, cur)
    return best

def climbStairs(n):
    a = b = 1
    for _ in range(n - 1):
        a, b = b, a + b
    return b

def containsDuplicate(nums):
    seen = set()
    for n in nums:
        if n in seen:
            return True
        seen.add(n)
    return False

def plusOne(digits):
    for i in range(len(digits) - 1, -1, -1):
        if digits[i] < 9:
            digits[i] += 1
            return digits
        digits[i] = 0
    return [1] + digits

def isPalindrome(s):
    l, r = 0, len(s) - 1
    while l < r:
        while l < r and not s[l].isalnum():
            l += 1
        while l < r and not s[r].isalnum():
            r -= 1
        if s[l].lower() != s[r].lower():
            return False
        l += 1; r -= 1
    return True

def longestCommonPrefix(strs):
    if not strs:
        return ""
    for i in range(len(strs[0])):
        ch = strs[0][i]
        for s in strs[1:]:
            if i >= len(s) or s[i] != ch:
                return strs[0][:i]
    return strs[0]

def romanToInt(s):
    v = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    for i in range(len(s)):
        if i+1 < len(s) and v[s[i]] < v[s[i+1]]:
            total -= v[s[i]]
        else:
            total += v[s[i]]
    return total

def firstUniqChar(s):
    from collections import Counter
    c = Counter(s)
    for i, ch in enumerate(s):
        if c[ch] == 1:
            return i
    return -1

def isHappy(n):
    seen = set()
    while n != 1 and n not in seen:
        seen.add(n)
        n = sum(int(d)**2 for d in str(n))
    return n == 1

def canConstruct(ransomNote, magazine):
    from collections import Counter
    m = Counter(magazine)
    for ch in ransomNote:
        if m[ch] <= 0:
            return False
        m[ch] -= 1
    return True

def majorityElement(nums):
    candidate = None
    count = 0
    for n in nums:
        if count == 0:
            candidate = n
        count += 1 if n == candidate else -1
    return candidate

def singleNumber(nums):
    x = 0
    for n in nums:
        x ^= n
    return x

def missingNumber(nums):
    x = len(nums)
    for i, n in enumerate(nums):
        x ^= i ^ n
    return x

def sortedSquares(nums):
    n = len(nums)
    res = [0]*n
    l, r = 0, n-1
    for i in range(n-1, -1, -1):
        if abs(nums[l]) > abs(nums[r]):
            res[i] = nums[l]**2; l += 1
        else:
            res[i] = nums[r]**2; r -= 1
    return res

def topKFrequent(nums, k):
    from collections import Counter
    import heapq
    c = Counter(nums)
    return heapq.nlargest(k, c.keys(), key=lambda x: c[x])

def productExceptSelf(nums):
    n = len(nums)
    res = [1]*n
    p = 1
    for i in range(n):
        res[i] = p; p *= nums[i]
    p = 1
    for i in range(n-1, -1, -1):
        res[i] *= p; p *= nums[i]
    return res

def letterCombinations(digits):
    if not digits:
        return []
    m = {'2':'abc','3':'def','4':'ghi','5':'jkl','6':'mno','7':'pqrs','8':'tuv','9':'wxyz'}
    res = ['' ]
    for d in digits:
        res = [r + ch for r in res for ch in m[d]]
    return res

def maxArea(height):
    l, r = 0, len(height)-1
    best = 0
    while l < r:
        best = max(best, (r-l) * min(height[l], height[r]))
        if height[l] < height[r]:
            l += 1
        else:
            r -= 1
    return best

def rob(nums):
    prev = prev2 = 0
    for x in nums:
        prev, prev2 = max(prev2 + x, prev), prev
    return prev

def coinChange(coins, amount):
    dp = [amount+1]*(amount+1)
    dp[0] = 0
    for a in range(1, amount+1):
        for c in coins:
            if c <= a:
                dp[a] = min(dp[a], dp[a-c] + 1)
    return dp[amount] if dp[amount] <= amount else -1

def canFinish(numCourses, prerequisites):
    from collections import deque
    adj = [[] for _ in range(numCourses)]
    indeg = [0]*numCourses
    for a, b in prerequisites:
        adj[b].append(a); indeg[a] += 1
    q = deque(i for i in range(numCourses) if indeg[i]==0)
    seen = 0
    while q:
        u = q.popleft(); seen += 1
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0: q.append(v)
    return seen == numCourses

def numIslands(grid):
    if not grid: return 0
    m, n = len(grid), len(grid[0])
    def sink(r, c):
        if r<0 or c<0 or r>=m or c>=n or grid[r][c] != '1': return
        grid[r][c] = '0'
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)): sink(r+dr, c+dc)
    count = 0
    for r in range(m):
        for c in range(n):
            if grid[r][c] == '1':
                sink(r, c); count += 1
    return count

def subsets(nums):
    res = [[]]
    for n in nums:
        res += [r + [n] for r in res]
    return res

