        res = []
        i = j = 0
        while i < len(x) and j < len(y):
            if x[i] <= y[j]:
                res.append(x[i]); i += 1
            else:
                res.append(y[j]); j += 1
        res.extend(x[i:])
        res.extend(y[j:])
        return res
    def msort(a):
        if len(a) <= 1:
            return a
        mid = len(a) // 2
        return merge(msort(a[:mid]), msort(a[mid:]))
